   const frames=Array.from({length:9},(_,j)=>{const u=j/8,v=1-u;return {transform:`translate(${v*v*x+2*v*u*cx+u*u*tx}px,${v*v*y+2*v*u*cy+u*u*ty}px)`,opacity:j===0||j===8?0:k?.75:1,offset:u}});
