function finish(){document.querySelector('.board-frame').classList.remove('casting');busy=false;queue=null;$('#skip').hidden=true;pulse(18);render();fade=setTimeout(()=>{$('#chain').classList.remove('show');document.querySelector('.board-frame').dataset.heat=0},1000);if(hit.size===L().targets.length){recordAttempt(true);if(index>=0&&index<levels.length){const progress=markCompletion(completed,index);completed=progress.completed;adDue=adDue||progress.adDue;}tone(0,true);pulse([20,70,20]);const rating=rateRun(L(),used,best,assisted),medal=rating.medal;const record={taps:used,medal,stars:rating.stars,bestChain:best,assisted};if(isBetterResult(record,medals[index]))medals[index]=record;persist();$('#instruction').textContent='Every target cleared.';resultTimer=setTimeout(()=>showResult(true,medal),1000)}else if(used>=tapBudget()){recordAttempt(false);$('#instruction').textContent='Out of taps. Undo or try again.';resultTimer=setTimeout(()=>showResult(false),500)}else {readySince=performance.now();$('#instruction').textContent=L().setupLesson&&wave===0?'Orb added. Fill its sockets to burst.':'Burst every amber target.';}}
