function show(content,kind=''){clearFirstTapHint();stopThinking();paused=true;render();clearTimeout(timer);modal.className=kind;$('#modalContent').innerHTML=content;modal.showModal()}
function showResult(win,medal){const rating=rateRun(L(),used,best,assisted);medal=rating.medal;show(win?`<h2>${L().planning?'Plan complete!':'Level complete!'}</h2><div class="result-stars" aria-label="${rating.stars} out of 3 stars">${[0,1,2].map(i=>`<span class="${i<rating.stars?'earned':''}">★</span>`).join('')}</div><div class="result-stats"><div><strong>${used}</strong><span>Taps used</span></div><div><strong>${L().planning?L().budget:L().par}</strong><span>${L().planning?'Plan taps':'Minimum'}</span></div><div><strong>${best}</strong><span>Best chain</span></div></div>${rating.chainAward||assisted?`<div class="result-award">${rating.chainAward?(rating.bonus?'✦ Chain bonus +1 star':'✦ Long-chain award'):''}${assisted?(rating.chainAward?' · Assisted':'Assisted'):''}</div>`:''}<button class="primary" id="next">${index===-1?'Back to puzzles':'Continue'}</button><button class="replay-link" id="retry">Play again</button>`:`<div class="overline">PUZZLE ${index===-1?'DOUBLE IGNITION':pad(index+1)}</div><h2>One more try?</h2><p>${L().targets.length-hit.size} ${L().targets.length-hit.size===1?'target remains':'targets remain'}. Every retry starts from the same board.<br><b>${L().planning?'Required plan: '+L().budget:'Minimum: '+L().par} taps</b></p><button class="primary" id="resultUndo">Undo last tap</button><button class="secondary" id="retry">Restart puzzle</button>${powersAvailable()?'<button class="secondary" id="rescue">Use a power</button>':''}`,win?'result victory':'result');$('#retry').onclick=()=>load(index);if(win)$('#next').onclick=()=>advance(()=>index===-1?levelMenu():load(index+1));else {$('#resultUndo').onclick=undo;if($('#rescue'))$('#rescue').onclick=powerMenu;}}
function levelMenu(){if(busy)return;clearTimeout(resultTimer);const recent=Array.from({length:Math.min(9,Math.max(0,furthest-levels.length+1))},(_,k)=>Math.max(levels.length,furthest-8)+k);const tile=i=>`<button class="${i===index?'active ':''}${medals[i]?'done':''}" data-level="${i}">${pad(i+1)}<small>${medals[i]?medals[i].medal+(medals[i].assisted?' · Magic':''):i<levels.length?'PAR '+levels[i].par:'GENERATED'}</small></button>`;
 show(`<button class="close" id="close" aria-label="Close">×</button><div class="overline">KEEP THE CHAIN GOING</div><h2>Choose a puzzle</h2><button class="primary" id="experiment">Double Ignition · 6×6 challenge</button><div class="level-grid">${levels.map((_,i)=>tile(i)).join('')}</div><button class="primary" id="fresh">New generated puzzle ↗</button>${recent.length?'<p>Recent generated puzzles</p><div class="level-grid">'+recent.map(tile).join('')+'</div>':''}`);$('#close').onclick=close;$('#experiment').onclick=()=>load(-1);$('#fresh').onclick=()=>load(Math.max(levels.length,furthest+1));modal.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>load(+b.dataset.level))}

function settings(){clearTimeout(resultTimer);show(`<button class="close" id="close" aria-label="Resume">×</button><div class="overline">TAKE A BREATH</div><h2>Paused</h2><label>Sound<input id="soundPref" type="checkbox" ${prefs.sound?'checked':''}></label><label>Haptics<input id="hapticPref" type="checkbox" ${prefs.haptics?'checked':''}></label><label>Debug overlay<input id="debugPref" type="checkbox" ${prefs.debug?'checked':''}></label><p>Tap to add an orb. Fill every socket to burst. Burst every amber target within the tap budget.</p><p>Difficulty rises in stages, with a free-flow puzzle every fifth generated level. Thinking time and attempts stay on this device.</p><p>Haptics play on supported devices. Reduced motion follows your device settings.</p><button class="primary" id="resume">Resume</button>`);$('#close').onclick=$('#resume').onclick=()=>{close();render();if(!busy&&hit.size===L().targets.length)resultTimer=setTimeout(()=>showResult(true,medals[index].medal),300)};for(const [id,key] of [['soundPref','sound'],['hapticPref','haptics'],['debugPref','debug']])$('#'+id).onchange=e=>{prefs[key]=e.target.checked;persist();render()}}
$('#undo').onclick=undo;$('#restart').onclick=()=>load(index);$('#sound').onclick=()=>{prefs.sound=!prefs.sound;persist();render();if(prefs.sound)tone()};$('#levels').onclick=$('#levelLabel').onclick=levelMenu;$('#settings').onclick=settings;$('#help').onclick=tileGuide;$('#skip').onclick=()=>{if(!queue)return;clearTimeout(timer);while(queue.position<queue.events.length)apply(queue.events[queue.position++]);finish()};modal.addEventListener('cancel',e=>{e.preventDefault();if(modal.classList.contains('tutorial'))return;close();render()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!modal.open)settings()});window.addEventListener('blur',()=>{if(!modal.open)settings()});$('#powers').onclick=powerMenu;$('#nova').onclick=useNova;$('#rowPower').onclick=selectRow;load(Number.isSafeInteger(saved.campaignCurrent)&&saved.campaignCurrent>=-1?saved.campaignCurrent:0);

function tileGuide(){if(busy)return;clearTimeout(resultTimer);show(`<button class="close" id="guideClose" aria-label="Close">×</button><h2>How to play</h2><p>Tap a tile to revisit its explanation.</p><div class="guide-list">${tutorials.filter(t=>t.id!=='powers2'||powersAvailable()).map(t=>`<button class="guide-item" data-guide="${t.id}">${tutorialArt(t.visual,true)}<span>${t.title}</span><b aria-hidden="true">›</b></button>`).join('')}</div><button class="primary" id="guidePlay">Back to game</button>`,'guide');$('#guideClose').onclick=$('#guidePlay').onclick=close;modal.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>showIntro(tutorials.find(t=>t.id===b.dataset.guide),[],true));}
function labHint(){if(busy)return;clearTimeout(resultTimer);show(`<button class="close" id="hintClose" aria-label="Close">×</button><div class="overline">A SMALL NUDGE</div><h2>Follow the left side</h2><p>The two shielded targets are linked through the left side of the board. Look for pads that feed that path, then consider what the bottom-right corner can add.</p><p>You can leave several charging pads untouched. A quiet tap can prepare a later cascade.</p><button class="primary" id="hintPlay">Try it</button>`);$('#hintClose').onclick=$('#hintPlay').onclick=close;}

function snapshot(tap){history.push({board:board.slice(),slots:slots.map(x=>x.slice()),hit:[...hit],targetHits:targetHits.slice(),used,best,tap,bonusTaps,assisted,powers:{...powers}})}
function tutorialArt(type,small=false){if(type==='powers')return `<div class="tutorial-art power-demo" aria-hidden="true"><span>+1</span><span>✦</span></div>`;const tile=(kind,target=false,filled=2,shield='')=>`<div class="demo-tile cell ${kind} ${shield?'shielded':''}">${[0,1,2,3].map(d=>`<i class="socket ${d<filled?'filled':''}" data-d="${d}"></i>`).join('')}${target?'<i class="target-ring"></i>':''}${shield?`<span class="shield-count">${shield}</span>`:''}</div>`;return `<div class="tutorial-art ${small?'compact':''}" aria-hidden="true">${type==='relay'?tile('charge-pad',false,1)+'<span class="demo-arrow">›</span>'+tile('relay',true,2):type==='shield'?tile('relay',true,2,'2')+'<span class="demo-arrow">›</span>'+tile('relay shield-weakened',true,2,'1'):type==='planning'?tile('charge-pad',false,4)+'<span class="demo-count">1 · 2 · 3<br><small>then burst!</small></span>':tile('charge-pad',type==='target',3)}</div>`}
function showIntro(info,remaining=[],fromGuide=false){show(`<h2>${info.title}</h2>${tutorialArt(info.visual)}<p>${info.body}</p>${remaining.length?`<div class="tutorial-more">${remaining.length} more quick ${remaining.length===1?'tip':'tips'}</div>`:''}<button class="primary" id="introPlay">${fromGuide?'Back to guide':remaining.length?'Got it':'Let’s play!'}</button>`,'tutorial');$('#introPlay').onclick=()=>{if(!fromGuide&&!introSeen.includes(info.id)){introSeen.push(info.id);persist()}if(fromGuide)tileGuide();else if(remaining.length)showIntro(remaining[0],remaining.slice(1));else close()}}
function powerMenu(){if(!powersAvailable()||busy)return;clearTimeout(resultTimer);show(`<button class="close" id="powerClose" aria-label="Close">×</button><h2>Magic at your fingertips</h2><p><b>Nova</b><br>Add one orb to every tile. The spell absorbs surplus energy so the cascade finishes. Ignites immediately, including in planning mode.</p><p><b>Row sweep</b><br>Tap a target to clear every target in its horizontal row, including shields.</p><p>Neither power uses a tap. Free prototype charges. Results using magic are marked assisted.</p><button class="primary" id="powerCloseButton">Back to game</button><button class="secondary" id="refill">Refill free test powers</button>`);$('#powerClose').onclick=$('#powerCloseButton').onclick=close;$('#refill').onclick=()=>{powers={nova:3,row:3};persist();close()}}
function selectRow(){if(!powersAvailable()||busy||hit.size===L().targets.length||powers.row<=0)return;clearTimeout(resultTimer);targeting=!targeting;clearFirstTapHint();if(modal.open)close();$('#instruction').textContent=targeting?'Tap a target to sweep its whole row.':'Row sweep cancelled.';render();if(!targeting)armFirstTapHint()}
function useNova(){if(!powersAvailable()||busy||paused||hit.size===L().targets.length||powers.nova<=0)return;clearTimeout(resultTimer);finishFirstTapHint();stopThinking();const r=nova(L().n,board,tapBudget()-used);snapshot();powers.nova--;assisted=true;targeting=false;chain=wave=0;board=r.charged.slice();slots=makeSlots(board);busy=true;started=performance.now();queue={events:r.waves,position:0,final:r.board};persist();render();$('#instruction').textContent='NOVA! Every tile charged.';document.querySelector('.board-frame').classList.add('casting');const rect=$('#magic').getBoundingClientRect();magic.blast(rect.width/2,rect.height/2,rect.width*.4,3);tone(10);pulse([20,40,30]);timer=setTimeout(step,500)}
function useBreaker(i){if(!powersAvailable())return;if(!L().targets.includes(i)||hit.has(i)){ $('#instruction').textContent='Choose a remaining target in the row you want to clear.';return}const cleared=rowTargets(L(),i,[...hit]);finishFirstTapHint();snapshot();powers.row--;assisted=true;targeting=false;for(const j of cleared){targetHits[j]=L().required?.[j]||1;hit.add(j)}busy=true;render(cleared);animate({firing:cleared,transfers:[]});const cells=$('#board').querySelectorAll('.cell');for(let j=Math.floor(i/L().n)*L().n;j<(Math.floor(i/L().n)+1)*L().n;j++)if(!reduced.matches)cells[j].animate([{background:'#fff2aa',transform:'scale(1.12)'},{transform:'scale(1)'}],{duration:650,delay:(j%L().n)*35});pulse([20,40,20]);tone(9);persist();queue={events:[],position:0,final:board.slice()};timer=setTimeout(step,850)}
function advance(next){if(!adDue){next();return}show(`<div class="overline">AD BREAK · PROTOTYPE</div><h2>Five levels cleared.</h2><p>This is where an interstitial ad would appear. No real advertisement is loaded in this build.</p><button class="primary" id="adContinue">Continue playing</button>`);$('#adContinue').onclick=()=>{adDue=false;persist();next()}}

// Count idle time only while the board is available for interaction.
for(const event of ['pointerdown','keydown'])document.addEventListener(event,armFirstTapHint,{passive:true,capture:true});
